import React, { useEffect, useState, useRef } from 'react';
import { ExternalLink, Github } from 'lucide-react';

export default function ProjectsSection() {
  const [activeProject, setActiveProject] = useState(0);
  const sectionRef = useRef(null);

  const projects = [
    {
      title: 'Techzo',
      subtitle: 'Design Agency Template',
      description:
        'Techzo is a cutting-edge design agency template built to showcase innovation, digital expertise, and a bold creative presence online',
      tags: ['HTML5 & CSS', 'Framer Motion', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/1827805025.jpeg',
      gradient: 'from-blue-600/20 via-purple-600/20 to-pink-600/20',
      textGradient: 'from-blue-400 to-purple-400',
    },
    {
      title: 'Lumin Studio',
      subtitle: 'Modern Design Portfolio',
      description:
        'LuminStudio blends elegance and clarity — a modern design agency template crafted to highlight creative work and impress potential clients',
      tags: ['HTML5 & Tailwind CSS', 'React', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/429890704.jpeg',
      gradient: 'from-emerald-600/20 via-teal-600/20 to-cyan-600/20',
      textGradient: 'from-emerald-400 to-teal-400',
    },
    {
      title: 'Nubuilt',
      subtitle: 'Architecture Template',
      description:
        'Crafted with clean, semantic code — Nubuilt is a sleek architecture template built for performance, responsiveness, and timeless design.',
      tags: ['HTML5', 'CSS', 'GSAP'],
      image: 'https://ext.same-assets.com/498039404/1730903789.jpeg',
      gradient: 'from-orange-600/20 via-red-600/20 to-pink-600/20',
      textGradient: 'from-orange-400 to-red-400',
    },
    {
      title: 'Design Orbit',
      subtitle: 'Portfolio Website Template',
      description:
        'Bold, creative, and conversion-focused — DesignOrbit is a sleek portfolio website template made for design agencies to showcase their work and attract clients.',
      tags: ['HTML5 & CSS', 'GSAP', 'Vite'],
      image: 'https://ext.same-assets.com/498039404/3079166500.jpeg',
      gradient: 'from-violet-600/20 via-purple-600/20 to-indigo-600/20',
      textGradient: 'from-violet-400 to-purple-400',
    },
  ];

  useEffect(() => {
    const handleScroll = () => {
      if (!sectionRef.current) return;

      const sectionTop = sectionRef.current.offsetTop;
      const scrollY = window.scrollY;
      const windowHeight = window.innerHeight;

      // Calculate which project should be active based on scroll position
      const projectHeight = windowHeight;
      const relativeScroll = scrollY - sectionTop;
      const currentProject = Math.floor(relativeScroll / projectHeight);

      if (currentProject >= 0 && currentProject < projects.length) {
        setActiveProject(currentProject);
      }
    };

    window.addEventListener('scroll', handleScroll);
    handleScroll(); // Initial call

    return () => window.removeEventListener('scroll', handleScroll);
  }, [projects.length]);

  return (
    <section ref={sectionRef} className="relative">
      {/* Projects Container */}
      <div style={{ height: `${projects.length * 100}vh` }}>
        {projects.map((project, index) => (
          <div
            key={index}
            className="sticky top-0 w-full h-screen flex items-center justify-center overflow-hidden"
            style={{
              zIndex: projects.length - index,
            }}
          >
            {/* Background with Gradient */}
            <div
              className={`absolute inset-0 bg-gradient-to-br ${project.gradient}`}
              style={{
                background: `
                  radial-gradient(circle at 30% 20%, rgba(59, 130, 246, 0.1) 0%, transparent 50%),
                  radial-gradient(circle at 70% 80%, rgba(168, 85, 247, 0.1) 0%, transparent 50%),
                  linear-gradient(135deg, rgba(0, 0, 0, 0.95) 0%, rgba(15, 23, 42, 0.98) 100%)
                `,
              }}
            />

            {/* Animated Background Elements */}
            <div className="absolute inset-0 overflow-hidden pointer-events-none">
              <div
                className="absolute top-20 left-20 w-64 h-64 bg-gradient-to-r from-white/5 to-transparent rounded-full blur-3xl animate-pulse"
                style={{
                  animationDelay: `${index * 0.5}s`,
                }}
              />
              <div
                className="absolute bottom-20 right-20 w-48 h-48 bg-gradient-to-r from-teal-500/10 to-transparent rounded-full blur-2xl animate-pulse"
                style={{
                  animationDelay: `${index * 0.3}s`,
                }}
              />
            </div>

            {/* Content */}
            <div className="relative z-10 w-full max-w-7xl mx-auto px-6 lg:px-16">
              <div className="grid lg:grid-cols-2 gap-16 items-center min-h-screen py-20">
                {/* Left Content */}
                <div className="space-y-8">
                  {/* Project Label */}
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-px bg-gradient-to-r from-transparent via-white/40 to-transparent" />
                    <span className="text-sm text-gray-400 font-mono tracking-wider">MY WORK</span>
                    <div className="w-12 h-px bg-gradient-to-r from-transparent via-white/40 to-transparent" />
                  </div>

                  {/* Project Title */}
                  <div className="space-y-4">
                    <h2
                      className={`text-5xl lg:text-7xl font-bold bg-gradient-to-r ${project.textGradient} bg-clip-text text-transparent leading-tight`}
                    >
                      {project.title}
                    </h2>
                    <p className="text-xl text-gray-300 font-light">{project.subtitle}</p>
                  </div>

                  {/* Description */}
                  <p className="text-lg text-gray-400 leading-relaxed max-w-lg">{project.description}</p>

                  {/* Tags */}
                  <div className="flex flex-wrap gap-3">
                    {project.tags.map((tag, tagIndex) => (
                      <div
                        key={tag}
                        className="px-4 py-2 text-sm font-medium bg-white/5 backdrop-blur-sm border border-white/20 text-white hover:bg-white/10 transition-all duration-300"
                        style={{
                          animationDelay: `${tagIndex * 0.1}s`,
                        }}
                      >
                        {tag}
                      </div>
                    ))}
                  </div>

                  {/* Action Buttons */}
                  <div className="flex gap-4 pt-4">
                    <button
                      className="group px-6 py-3 bg-transparent border-2 border-white/20 text-white font-semibold rounded-full hover:bg-white hover:text-black transition-all duration-300 hover:scale-105"
                    >
                      <ExternalLink className="w-4 h-4 mr-2 group-hover:rotate-45 transition-transform duration-300" />
                      Live Demo
                    </button>
                    <button
                      className="group px-6 py-3 bg-white/10 backdrop-blur-sm border-2 border-white/20 text-white font-semibold rounded-full hover:bg-white/20 transition-all duration-300 hover:scale-105"
                    >
                      <Github className="w-4 h-4 mr-2 group-hover:rotate-12 transition-transform duration-300" />
                      View Code
                    </button>
                  </div>
                </div>

                {/* Right Content - Project Image */}
                <div className="relative group">
                  {/* Main Image Container */}
                  <div className="relative rounded-2xl overflow-hidden bg-black/20 backdrop-blur-sm border border-white/10 hover:border-white/20 transition-all duration-500 hover:scale-105 hover:shadow-2xl hover:shadow-white/10">
                    <img
                      src={project.image || '/assets/placeholder.svg'}
                      alt={project.title}
                      className="w-full h-auto rounded-2xl transition-all duration-500 group-hover:scale-110"
                    />

                    {/* Overlay Gradient */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

                    {/* Floating Elements */}
                    <div className="absolute top-4 right-4 w-3 h-3 bg-white/30 rounded-full animate-ping opacity-0 group-hover:opacity-60 transition-opacity duration-500" />
                    <div className="absolute bottom-6 left-6 w-2 h-2 bg-teal-400/60 rounded-full animate-pulse opacity-0 group-hover:opacity-80 transition-opacity duration-700" />
                  </div>

                  {/* Decorative Elements */}
                  <div className="absolute -inset-4 bg-gradient-to-r from-white/5 via-transparent to-white/5 rounded-3xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 blur-xl -z-10" />
                  <div className="absolute top-8 -left-8 w-16 h-16 bg-gradient-to-r from-teal-500/20 to-blue-500/20 rounded-full blur-xl animate-pulse" />
                  <div className="absolute bottom-8 -right-8 w-20 h-20 bg-gradient-to-r from-purple-500/20 to-pink-500/20 rounded-full blur-xl animate-pulse" />
                </div>
              </div>
            </div>

            {/* Project Counter */}
            <div className="absolute bottom-8 right-8 flex items-center gap-4 text-white/60">
              <span className="text-sm font-mono">
                {String(index + 1).padStart(2, '0')} / {String(projects.length).padStart(2, '0')}
              </span>
              <div className="flex gap-1">
                {projects.map((_, dotIndex) => (
                  <div
                    key={dotIndex}
                    className={`w-2 h-2 rounded-full transition-all duration-300 ${
                      dotIndex === activeProject ? 'bg-white scale-125' : 'bg-white/30'
                    }`}
                  />
                ))}
              </div>
            </div>

            {/* Scroll Indicator (only on first project) */}
            {index === 0 && (
              <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 text-white/60 animate-bounce">
                <div className="flex flex-col items-center gap-2">
                  <span className="text-xs font-mono">SCROLL</span>
                  <div className="w-px h-8 bg-gradient-to-b from-white/60 to-transparent" />
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Final CTA Section */}
      <div className="relative h-screen flex items-center justify-center bg-gradient-to-br from-gray-900 via-black to-gray-900">
        <div className="text-center space-y-8 px-6">
          <h3 className="text-4xl lg:text-6xl font-bold text-white mb-4">Ready to Start Your Project?</h3>
          <p className="text-xl text-gray-400 max-w-2xl mx-auto">
            Let's collaborate and bring your vision to life with cutting-edge design and development.
          </p>
          <button
            onClick={() => {
              const link = document.createElement('a');
              link.href = '/assets/BadrEddineDiyaf.pdf';
              link.download = 'Badr_Eddine_Diyaf_CV.pdf';
              link.click();
            }}
            className="group px-8 py-4 text-lg bg-transparent border-2 border-teal-500 text-teal-400 font-semibold rounded-full overflow-hidden transition-all duration-300 hover:scale-105 hover:bg-teal-500 hover:text-white hover:shadow-2xl hover:shadow-teal-500/25"
          >
            {/* Button Background Animation */}
            <div className="absolute inset-0 bg-gradient-to-r from-teal-500 to-cyan-500 scale-x-0 group-hover:scale-x-100 transition-transform duration-300 origin-left" />

            {/* Button Content */}
            <span className="relative z-10 flex items-center justify-center gap-2">
              Download My Resume
              <svg
                className="w-4 h-4 transform group-hover:animate-bounce"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                />
              </svg>
            </span>

            {/* Glow Effect */}
            <div className="absolute -inset-1 bg-gradient-to-r from-teal-500/50 to-cyan-500/50 rounded-full opacity-0 group-hover:opacity-100 blur-sm transition-opacity duration-300 -z-10" />
          </button>
        </div>
      </div>
    </section>
  );
}
